tool_input.command:
cat > verify_weekly.js << 'EOF'
import { CYCLE, CYCLES, monthlyCents, nextCharge } from './src/cycles.js';
import { upcoming } from './src/renewals.js';

console.log('✓ Weekly cycle is recognized:');
console.log('  CYCLES:', CYCLES);
console.log('  Includes "weekly":', CYCLES.includes('weekly'));

const weeklyPlan = { name: 'Meal kit', price: 5990, cycle: 'weekly', since: '2026-10-25' };

console.log('\n✓ Weekly monthly cost calculation:');
console.log('  €59.90/week = €' + (monthlyCents(weeklyPlan) / 100).toFixed(2) + '/month');
console.log('  Expected: €259.57/month (59.90 × 52 ÷ 12)');

console.log('\n✓ Weekly charging pattern (every 7 days):');
console.log('  First charge (since):', nextCharge(weeklyPlan, '2026-10-24'));
console.log('  Next from 2026-10-26:', nextCharge(weeklyPlan, '2026-10-26'));
console.log('  Next from 2026-11-02:', nextCharge(weeklyPlan, '2026-11-02'));

const subs = [weeklyPlan];
console.log('\n✓ Renewals for weekly plan:');
const renewals = upcoming(subs, '2026-10-25', 30);
renewals.forEach(r => {
  console.log(`  ${r.date} (${r.when}): €${(r.price / 100).toFixed(2)}`);
});
EOF
node verify_weekly.js && rm verify_weekly.js
